CASE BLUF: Raw string set intersection fails on both honorific aliases and same-name collisions; match on `(last_name, first_initial, dob)` tuples and quarantine records missing DOB.
1. AUDIT FINDING: Any person-entity join must require a verified `dob` or hard identifier to avoid merging two distinct `'John Kim'` records.
```python
from typing import List, Dict, Tuple

def safe_person_join(
    list_a: List[Dict[str, str]],
    list_b: List[Dict[str, str]],
) -> Tuple[List[str], List[str]]:
    keyed_a = {}
    collisions: List[str] = []
    for p in list_a:
        if not p.get('dob'):
            collisions.append(f"HOLD_NO_DOB:{p['raw_name']}")
        else:
            keyed_a[(p['last_norm'], p['first_init'], p['dob'])] = p['raw_name']
    verified_matches: List[str] = []
    for p in list_b:
        if not p.get('dob'):
            collisions.append(f"HOLD_NO_DOB:{p['raw_name']}")
        else:
            k = (p['last_norm'], p['first_init'], p['dob'])
            if k in keyed_a:
                verified_matches.append(f"{keyed_a[k]} == {p['raw_name']} ({p['dob']})")
    return verified_matches, collisions
```
2. NEXT LEAD: Run `safe_person_join` on the normalized `doc01` and `doc02` person registries.

CASE BLUF: Interviewer longitudinal statement auditor detects value changes across years (`TOPIC_VALUE_DRIFT`) and identifies mandatory case topics never covered with the witness (`UNASKED_TOPIC_GAP`).
1. INTERVIEWER DOCTRINE: Track what changed and what was never asked across every statement year without labeling the witness truthful or untruthful.
2. INNOCENT ALTERNATIVE: Natural memory decay over a multi-year gap or different phrasing of a narrow question by two detectives can shift peripheral time/color details.
```python
from collections import defaultdict
from typing import List, Dict, Any

def audit_longitudinal_statements(
    interviews: List[Dict[str, Any]],
    required_topics: set[str],
) -> Dict[str, Any]:
    ordered = sorted(interviews, key=lambda x: str(x['date_iso']))
    history_by_topic: Dict[str, List[Dict[str, str]]] = defaultdict(list)
    covered_topics: set[str] = set()

    for iv in ordered:
        doc_id = str(iv['doc_id'])
        dt = str(iv['date_iso'])
        for topic, val in iv.get('claims', {}).items():
            covered_topics.add(topic)
            history_by_topic[topic].append({
                'doc_id': doc_id,
                'date_iso': dt,
                'value': str(val).strip(),
            })

    drifts: List[Dict[str, Any]] = []
    for topic, entries in sorted(history_by_topic.items()):
        distinct_vals = {e['value'] for e in entries}
        if len(distinct_vals) > 1:
            drifts.append({
                'topic': topic,
                'status': 'TOPIC_VALUE_DRIFT',
                'chronology': entries,
            })

    unasked = sorted(required_topics - covered_topics)
    return {
        'drift_count': len(drifts),
        'topic_drifts': drifts,
        'unasked_topic_gaps': unasked,
    }
```
3. NEXT LEAD: Draft non-leading PEACE questions anchored directly to each `unasked_topic_gaps` item and `topic_drifts` pair.

CASE BLUF: Records collision classifier blocks accidental identity merges on shared names and separates confirmed hard conflicts (`HARD_COLLISION_DO_NOT_MERGE`) from under-specified records (`INSUFFICIENT_IDENTIFIER_HOLD`).
1. RECORDS DOCTRINE: Two people with one name is normal; merging them without a matching hard identifier (`DOB + SSN4` or `DL`) is the one error Records never makes.
```python
from typing import Dict, Any

def evaluate_person_collision(
    cand_a: Dict[str, str],
    cand_b: Dict[str, str],
) -> Dict[str, Any]:
    hard_conflicts = []
    hard_matches = []

    for field in ('dob', 'ssn_last4', 'dl_state_num', 'middle_initial'):
        va = str(cand_a.get(field, '')).strip().upper()
        vb = str(cand_b.get(field, '')).strip().upper()
        if va and vb:
            if va != vb:
                hard_conflicts.append(field)
            elif field in ('dob', 'ssn_last4', 'dl_state_num'):
                hard_matches.append(field)

    if hard_conflicts:
        status = 'HARD_COLLISION_DO_NOT_MERGE'
    elif len(hard_matches) >= 2 or 'dl_state_num' in hard_matches:
        status = 'VERIFIED_SAME_PERSON'
    else:
        status = 'INSUFFICIENT_IDENTIFIER_HOLD'

    return {
        'disposition': status,
        'hard_matches': hard_matches,
        'hard_conflicts': hard_conflicts,
    }
```
2. NEXT LEAD: Keep any `INSUFFICIENT_IDENTIFIER_HOLD` pair split onto separate person cards until DMV or vital-statistics records supply a second hard identifier.

CASE BLUF: Comparing only dictionary `.keys()` checks item categories while ignoring quantity divergences (`7 vs 5 casings`); a CSI reconciler must verify both set equality on item keys and exact integer equality on counts.
1. CSI DOCTRINE: Paper about objects must agree on exact counts because courtrooms eat inexact counts alive.
```python
from typing import Dict, Any, List

def reconcile_csi_item_counts(
    scene_counts: Dict[str, int],
    ledger_counts: Dict[str, int],
) -> Dict[str, Any]:
    mentioned_not_logged: List[str] = []
    logged_not_mentioned: List[str] = []
    count_mismatches: List[Dict[str, Any]] = []

    all_items = sorted(set(scene_counts) | set(ledger_counts))
    for item in all_items:
        in_scene = item in scene_counts
        in_ledger = item in ledger_counts
        if in_scene and not in_ledger:
            mentioned_not_logged.append(item)
        elif in_ledger and not in_scene:
            logged_not_mentioned.append(item)
        else:
            s_qty = int(scene_counts[item])
            l_qty = int(ledger_counts[item])
            if s_qty != l_qty:
                count_mismatches.append({
                    'item': item,
                    'scene_qty': s_qty,
                    'ledger_qty': l_qty,
                    'delta': l_qty - s_qty,
                })

    return {
        'reconciled': not (mentioned_not_logged or logged_not_mentioned or count_mismatches),
        'mentioned_not_logged': mentioned_not_logged,
        'logged_not_mentioned': logged_not_mentioned,
        'count_mismatches': count_mismatches,
    }
```

CASE BLUF: A dict comprehension `{r['item']: r['qty'] ...}` overwrites earlier voucher rows sharing the same item key (`dropping V1's 5 casings and keeping only V2's 2`); sum quantities across all vouchers with `collections.Counter` while preserving the voucher ID list.
1. AUDIT FINDING: Multi-voucher evidence collections routinely split identical items by recovery zone (`North Kitchen` vs `Under Fridge`).
```python
from collections import defaultdict
from typing import List, Dict, Any

def aggregate_voucher_rows(
    voucher_rows: List[Dict[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    totals: Dict[str, int] = defaultdict(int)
    vouchers_by_item: Dict[str, List[str]] = defaultdict(list)
    for r in voucher_rows:
        key = str(r['item']).strip()
        qty = int(r['qty'])
        if qty < 0:
            raise ValueError(f'negative quantity on voucher {r}')
        totals[key] += qty
        vouchers_by_item[key].append(str(r['voucher_id']))
    return {
        k: {'total_qty': totals[k], 'vouchers': vouchers_by_item[k]}
        for k in sorted(totals)
    }
```

CASE BLUF: Python temporal-and-value-constrained cycle finder traverses `doc14_wires` to isolate 3-hop and 4-hop round-trip laundering loops where timestamps increase monotonically and per-hop value retention stays `>= 90%`.
1. AUDIT FINDING: Enforcing `ts_next >= ts_curr` and `0.90 <= amt_next / amt_curr <= 1.02` eliminates false graph cycles caused by out-of-order historical trades and isolates active principal pass-through loops.
2. INNOCENT ALTERNATIVE: Multi-currency treasury sweep circuits across regional bank subsidiaries can exhibit rapid sequential rebalancing during quarter-end liquidity settlement.
```python
from collections import defaultdict

def find_temporal_roundtrip_loops(wires: list[dict], max_hops: int = 4) -> list[dict]:
    adj: dict[str, list[dict]] = defaultdict(list)
    for w in wires:
        adj[w["sender"]].append(w)
    loops = []

    def dfs(origin: str, curr: str, path_nodes: list[str], first_amt: float, last_amt: float, last_ts: int) -> None:
        if len(path_nodes) - 1 > max_hops:
            return
        for edge in adj[curr]:
            nxt = edge["receiver"]
            amt = float(edge["amount_usd"])
            ts = int(edge["ts"])
            if ts < last_ts or not (0.90 <= amt / last_amt <= 1.02):
                continue
            if nxt == origin and len(path_nodes) >= 3:
                loops.append({
                    "cycle": path_nodes + [origin],
                    "origin_usd": first_amt,
                    "returned_usd": amt,
                    "net_retention_pct": round(100.0 * amt / first_amt, 2),
                })
            elif nxt not in path_nodes and len(path_nodes) < max_hops:
                dfs(origin, nxt, path_nodes + [nxt], first_amt, amt, ts)

    for w in wires:
        dfs(w["sender"], w["receiver"], [w["sender"], w["receiver"]], float(w["amount_usd"]), float(w["amount_usd"]), int(w["ts"]))
    return loops

sample_wires = [
    {"sender": "CORP_A", "receiver": "SHELL_B", "amount_usd": 500000.0, "ts": 1733200000},
    {"sender": "SHELL_B", "receiver": "TRUST_C", "amount_usd": 490000.0, "ts": 1733210000},
    {"sender": "TRUST_C", "receiver": "CORP_A", "amount_usd": 482000.0, "ts": 1733220000},
]
print(find_temporal_roundtrip_loops(sample_wires))
```

